fn swap_first_and_last(a: &mut Vec<i32>) {
    // If there's more than one element, swap the first and last.
    if a.len() > 1 {
        let last_index = a.len() - 1;
        a.swap(0, last_index);
    }
}

fn main() {
    let mut v1 = vec![1, 2, 3, 4];
    swap_first_and_last(&mut v1);
    assert_eq!(v1, vec![4, 2, 3, 1]);

    let mut v2 = vec![10];
    swap_first_and_last(&mut v2);
    assert_eq!(v2, vec![10]);

    println!("All tests passed!");
}